// Regenerate src/api/types.ts: one re-export per ts-rs binding, plus the hand-written composites.
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "src", "api");
const names = readdirSync(join(dir, "bindings")).filter((f) => f.endsWith(".ts")).map((f) => f.slice(0, -3)).sort();
const lines = [
  "// Generated by scripts/types-index.mjs (npm run bindings). Types shared with the Rust core come",
  "// from ./bindings (ts-rs); the composites built in the command layer are in ./composite.",
  ...names.map((n) => `export type { ${n} } from "./bindings/${n}";`),
  'export type * from "./composite";',
  "",
];
writeFileSync(join(dir, "types.ts"), lines.join("\n"));
console.log(`types.ts: ${names.length} bindings`);
